SELECT CAST(CASE WHEN typeof(id)='text' THEN id END AS TEXT) AS id,database,attempt,request_epoch,holder,answer_kind,recorded_epoch,CAST(recorded_expires_at AS TEXT) AS recorded_expires_at,current_database,current_holder,current_state,current_epoch,current_remaining_ms,CAST(current_expires_at AS TEXT) AS current_expires_at,transfer_in_progress,CAST(replayed AS TEXT) AS replayed,refusal_kind,refusal_current_epoch,refusal_ended_epoch,refusal_ended_sequence FROM _fleet_sync_renewal_attempts WHERE database=?1 AND attempt=?2
